"use client";

import { unwrap, useApiQuery, useBffClient } from "@/lib/bff/query";
import type { Loadable } from "@/lib/loadable";
import * as z from "@/lib/zod";
import { ifMatch, type VerifiedAnswerBody } from "./data";

/**
 * Knowledge gaps (FA-06; FR-KB-085..FR-KB-090; docs/09 Knowledge gaps): questions Ask could not
 * answer, for holders of `kb.verified_answer.manage`.
 *
 * The routes are new in this wave and not yet in the generated client
 * (`packages/api-client`, regenerated by `make openapi`), so the bodies are checked here with
 * zod and the calls go through an untyped view of the same BFF client (CSRF, step-up and 401
 * handling unchanged). After regeneration: replace these schemas with
 * `components["schemas"]["KnowledgeGapOut" | "KnowledgeGapSummaryOut" | "KnowledgeGapCloseIn"]`
 * and call `api.GET("/api/v1/knowledge/gaps", ...)` typed.
 */

export const knowledgeGapSchema = z.object({
  id: z.string(),
  question: z.string().nullable(),
  language: z.enum(["en", "te"]).nullable(),
  occurrences: z.number(),
  not_found_count: z.number(),
  unchecked_count: z.number(),
  not_helpful_count: z.number(),
  first_seen_at: z.string(),
  last_seen_at: z.string(),
  status: z.enum(["open", "closed", "dismissed"]),
  resolution: z.enum(["verified_answer", "document"]).nullable(),
  verified_answer_id: z.string().nullable(),
  document_id: z.string().nullable(),
  closed_by: z.string().nullable(),
  closed_by_name: z.string().nullable(),
  closed_at: z.string().nullable(),
  version: z.number(),
});
export type KnowledgeGap = z.infer<typeof knowledgeGapSchema>;
export type GapStatus = KnowledgeGap["status"];

const gapPageSchema = z.object({
  data: z.array(knowledgeGapSchema),
  next_cursor: z.string().nullable(),
});
export type KnowledgeGapPage = z.infer<typeof gapPageSchema>;

export const gapSummarySchema = z.object({
  open_gaps: z.number(),
  not_found: z.number(),
  unchecked: z.number(),
  not_helpful: z.number(),
  months: z.array(
    z.object({
      month: z.string(),
      closed_with_answer: z.number(),
      closed_with_document: z.number(),
      dismissed: z.number(),
    }),
  ),
  retention_days: z.number(),
});
export type KnowledgeGapSummary = z.infer<typeof gapSummarySchema>;

export type GapCloseBody =
  | { resolution: "dismissed" }
  | { resolution: "document"; document_id: string }
  | { resolution: "verified_answer"; verified_answer_id: string };

export const GAP_KEYS = {
  all: ["staff", "knowledge", "gaps"],
  list: (status: GapStatus, cursor: string | undefined) =>
    ["staff", "knowledge", "gaps", "list", status, cursor ?? null] as const,
  summary: ["staff", "knowledge", "gaps", "summary"],
} as const;

type RawResult = { data?: unknown; error?: unknown; response: Response };
interface RawInit {
  params?: { path?: Record<string, string>; query?: Record<string, string | number> };
  headers?: Record<string, string>;
  body?: unknown;
}
/** The BFF client without path typing (see the module comment). */
interface RawClient {
  GET(path: string, init?: RawInit): Promise<RawResult>;
  POST(path: string, init?: RawInit): Promise<RawResult>;
}

function useRawClient(): RawClient {
  return useBffClient("staff") as unknown as RawClient;
}

/** GET /knowledge/gaps (open: most asked first; closed and dismissed: newest first). */
export function useKnowledgeGaps(
  status: GapStatus,
  cursor: string | undefined,
  enabled: boolean,
): Loadable<KnowledgeGapPage> {
  const api = useRawClient();
  return useApiQuery(
    GAP_KEYS.list(status, cursor),
    async () =>
      gapPageSchema.parse(
        await unwrap(
          api.GET("/api/v1/knowledge/gaps", {
            params: { query: { status, limit: 20, ...(cursor ? { cursor } : {}) } },
          }),
        ),
      ),
    { enabled },
  );
}

/** GET /knowledge/gaps/summary (counts only). */
export function useGapSummary(enabled: boolean): Loadable<KnowledgeGapSummary> {
  const api = useRawClient();
  return useApiQuery(
    GAP_KEYS.summary,
    async () => gapSummarySchema.parse(await unwrap(api.GET("/api/v1/knowledge/gaps/summary"))),
    { enabled },
  );
}

/** Close, dismiss or answer a gap (If-Match with the version listed). */
export function useGapApi() {
  const api = useRawClient();
  return {
    close: async (gap: KnowledgeGap, body: GapCloseBody) =>
      knowledgeGapSchema.parse(
        await unwrap(
          api.POST("/api/v1/knowledge/gaps/{gap_id}/close", {
            params: { path: { gap_id: gap.id } },
            headers: { "If-Match": ifMatch(gap.version) },
            body,
          }),
        ),
      ),
    answer: async (gap: KnowledgeGap, body: VerifiedAnswerBody) =>
      knowledgeGapSchema.parse(
        await unwrap(
          api.POST("/api/v1/knowledge/gaps/{gap_id}/verified-answer", {
            params: { path: { gap_id: gap.id } },
            headers: { "If-Match": ifMatch(gap.version) },
            body,
          }),
        ),
      ),
  };
}

const UUID = /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i;

/** The document id in a pasted document page link (`/documents/<id>`) or a bare id. */
export function documentIdFrom(value: string): string | null {
  const match = UUID.exec(value.trim());
  return match ? match[0].toLowerCase() : null;
}
